impl Drop for AppState {
    /// Flushes the background persistence actor. `shutdown` waits for the
    /// writer thread to finish its last flush, so a panic (or any other
    /// teardown) does not drop queued history/usage writes. A clean quit
    /// already called it in the Exit hook first, and the second call returns
    /// immediately because the first took the exit signal.
    fn drop(&mut self) {
        self.persist.shutdown();
    }
}

/// All app state, shared across commands and the dictation controller.
pub struct AppState {
    pub settings: Repo<commands::Settings>,
    pub autotext: Arc<Repo<AutoTextStore>>,
    pub transforms: Repo<TransformStore>,
    pub profile: Repo<UserProfile>,
    pub history: Repo<teletype_core::history::DictationHistory>,
    pub dictionary: Repo<Dictionary>,
    pub user_packs: Repo<UserPackStore>,
    pub styles: Repo<StyleProfileStore>,
    pub usage: Repo<teletype_core::usage::UsageStats>,
    pub scratchpad: Repo<Notes>,
    pub injector: TextInjector,
    pub controller: dictation::Controller,
    /// The most recent auto-learned take, for the undo offer (tray menu item
    /// and the main-window toast). Carries both the preference ids and the exact
    /// dictionary writes so undo can revert both stores. `None` when there is
    /// nothing to undo: never learned, already undone, or the offer expired.
    pub last_learned: Mutex<Option<commands::LearnedOffer>>,
    pub dictation_state: Mutex<teletype_core::state::UiState>,
    pub platform: Box<dyn Platform>,
    /// Background persistence writer (A4). History/usage disk writes go
    /// through this handle; the in-memory `Repo` snapshots stay the read
    /// source of truth. The actor flushes on drop (bounded), so a panic
    /// cannot lose queued entries.
    pub persist: persist::PersistHandle,
    /// The loaded inference provider, if any.
    ///
    /// P1.8: the provider is held behind an `Arc` so the dictation worker
    /// can clone a snapshot and drop the lock before the (up to 20 s) LLM
    /// call. Model-swap commands still take the lock briefly to replace the
    /// Arc, but no lock is held across generation.
    pub inference: Mutex<Option<std::sync::Arc<dyn teletype_core::llm::InferenceProvider>>>,
    /// Legacy slot, never populated: this decision provider (TinyDecide +
    /// Needle 3) is constructed only in tests and has no runtime consumer.
    /// NeuDecide, via `command_decider`, is the only wired decider.
    pub decision:
        std::sync::Arc<std::sync::Mutex<Option<Box<dyn teletype_core::llm::DecisionProvider>>>>,
    /// A.3.3: the selected command decider (NeuDecide when available, else
    /// Needle / LLM fallback). Rebuilt by `ensure_decision_provider`; read
